package com.bank.memory;

import java.util.logging.*;

public class StatementMemoryDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatementWriter writer = new StatementWriter();
        int lines = 10_000;

        // String approach: counts how many NEW String objects are created (one per edit).
        long stringObjects = writer.buildWithStringCountingAllocations("SAV2001", lines);
        log.warning(() -> "String approach created ~" + stringObjects
                           + " intermediate String objects (garbage)");

        // StringBuffer approach: one growable array, few reallocations.
        String result = writer.buildWithBuffer("SAV2001", lines);
        log.info(() -> "StringBuffer built length=" + result.length()
                        + " reusing ONE growable array");
    }
}

// ─── Would be StatementWriter.java in a real project ───
class StatementWriter {
    // Demonstrates String churn: each += allocates a brand-new String object.
    long buildWithStringCountingAllocations(String accountId, int lines) {
        String result = "Statement for " + accountId + "\n";
        long allocations = 1;
        for (int i = 0; i < lines; i++) {
            result = result + "Line " + i + "\n"; // NEW String each iteration
            allocations++;                          // each edit = new immutable object
        }
        return allocations; // ~ lines + 1 intermediate String objects created
    }

    // StringBuffer: one backing array, grows (doubles) only when full.
    String buildWithBuffer(String accountId, int lines) {
        // pre-size capacity to avoid even the doubling reallocations
        StringBuffer sb = new StringBuffer(lines * 12);
        sb.append("Statement for ").append(accountId).append("\n");
        for (int i = 0; i < lines; i++) {
            sb.append("Line ").append(i).append("\n"); // in-place, no new object
        }
        return sb.toString(); // build-then-freeze: ONE immutable String at the end
    }
}
